{
  "name": "model-router",
  "version": "0.4.1",
  "description": "Routes each subagent to the cheapest Claude model and effort that can do its task, judged by TypeSafe Jev",
  "author": {
    "name": "Akurganow",
    "url": "https://github.com/Akurganow"
  },
  "license": "MIT",
  "homepage": "https://github.com/Akurganow/model-router",
