  "privacyPolicyUrl": "https://github.com/Akurganow/model-router/blob/main/PRIVACY.md",
  "keywords": [
    "claude-code",
    "mod",
    "subagents",
    "model-routing",
    "typesafe",
    "jev"
  ],
  "userConfig": {
    "api_key": {
      "type": "string",
      "title": "TypeSafe API key",
      "description": "Sent only to https://api.typesafe.ai/v1/systemone as the bearer token. Get one at https://console.typesafe.ai/keys.",
      "sensitive": true
    },
    "mode": {
      "type": "string",
      "title": "Routing mode",
      "description": "suggest: log the model and effort Jev would pick, change nothing. auto: set the model and the effort. Only a model or effort passed in the Agent call is kept. Auto also overrides a model or effort pinned in an agent definition.",
      "options": [
        "suggest",
        "auto"
      ],
      "default": "suggest"
    }
  }
}
